// services/autoscaler/pkg/controller/burst_controller.go
func (b *BurstController) Admit(req Request) (bool, error) {
    // compute desired tokens based on request size and priority
    tokens := b.tokensFor(req)
    // smoothing reduces volatility across windows
    b.smooth(tokens)
    if b.bucket.TryConsume(tokens) {
        b.metrics.Inc("burst_consumed_tokens", tokens)
        return true, nil
    }
    // if request is high priority and within guaranteed throughput, allow with tracing tag
    if req.Priority == PriorityHigh && b.withinGuarantee(req.FleetID) {
        trace.SpanTag("burst.allow", "guarantee")
        return true, nil
    }
    return false, ErrTooManyRequests
}
